sed -i 's|<body>|<body>\n    <div id="log" style="position:fixed;top:0;left:0;z-index:9999;background:red;color:white;font-size:10px;padding:10px;white-space:pre-wrap;"></div>\n    <script>\n      const log = document.getElementById("log");\n      window.onerror = function(msg, url, lineNo, columnNo, error) {\n        log.textContent += "\\nError: " + msg + "\\nLine: " + lineNo + "\\nColumn: " + columnNo + "\\nError obj: " + (error ? error.stack : "");\n      };\n      window.onunhandledrejection = function(event) {\n        log.textContent += "\\nPromise Rejection: " + event.reason;\n      };\n      const originalConsoleError = console.error;\n      console.error = function(...args) {\n        log.textContent += "\\nConsole Error: " + args.join(" ");\n        originalConsoleError.apply(console, args);\n      };\n    </script>|g' index.html
